import torch


def gen_inputs(ctx, device):
    shape = ctx["input__shape"]
    dtype = ctx["input__dtype"]
    if isinstance(dtype, str):
        dtype = getattr(torch, dtype)
    if dtype == torch.bool:
        inp = torch.randint(0, 2, shape, dtype=torch.int, device=device).to(dtype)
    elif dtype in (torch.int16, torch.int32, torch.int64):
        inp = torch.randint(-3, 3, shape, device=device).to(dtype)
    else:
        inp = torch.randn(shape, dtype=dtype, device=device)
    return {"input": inp}


def run(input):
    return torch.nonzero(input)
